-- Тема 06: варианты ответов выровнены по длине и форме (52 исправлений в 19 вопросах), ключи не меняются.
-- Источник: scripts/questions/067_option_length_topic06.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Что делает очистка (VACUUM) в первую очередь?', 'Полностью перестраивает таблицу', 'Полностью перестраивает таблицу и её индексы', 'Так делает VACUUM FULL.', NULL),
        ('option', 'Что делает очистка (VACUUM) в первую очередь?', 'Удаляет старые файлы WAL', 'Удаляет старые файлы WAL после контрольной точки', 'Ненужные файлы WAL удаляются или переиспользуются после контрольной точки.', NULL),
        ('option', 'Что делает очистка (VACUUM) в первую очередь?', 'Удаляет мёртвые версии строк из таблиц и ссылки на них из индексов', 'Удаляет мёртвые версии строк и ссылки на них из индексов', 'Освободившееся место используется для новых версий строк.', NULL),
        ('option', 'Зачем нужна заморозка версий строк?', 'Чтобы запретить изменение строки', 'Чтобы запретить изменение старых версий строк таблицы', 'Замороженную строку можно изменять как обычно.', NULL),
        ('option', 'Зачем нужна заморозка версий строк?', 'Чтобы сжать данные', 'Чтобы сжать данные старых страниц таблицы', 'Заморозка данные не сжимает.', NULL),
        ('option', 'Зачем нужна заморозка версий строк?', 'Чтобы предотвратить последствия переполнения 32-битного счётчика транзакций', 'Чтобы защититься от оборота счётчика транзакций', 'Счётчик транзакций 32-битный и идёт по кругу; замороженная версия считается созданной в прошлом при любом значении счётчика.', NULL),
        ('option', 'Зачем нужна заморозка версий строк?', 'Чтобы ускорить репликацию', 'Чтобы реплики быстрее применяли журнал', 'К репликации заморозка не относится.', NULL),
        ('option', 'Что произойдёт, если не выполнять заморозку своевременно?', 'Сервер перестанет выделять новые номера транзакций и будет отклонять команды, которым они нужны', 'Сервер перестанет выдавать новые номера транзакций', 'Так сервер защищается от переполнения счётчика транзакций; нужна очистка с заморозкой.', 'Так сервер защищается от переполнения счётчика транзакций: команды, которым нужен новый номер, отклоняются; нужна очистка с заморозкой.'),
        ('option', 'Что произойдёт, если не выполнять заморозку своевременно?', 'Только немного замедлятся запросы', 'Запросы немного замедлятся из-за лишних проверок', 'Последствия гораздо серьёзнее: новые транзакции не получат номера.', NULL),
        ('option', 'Что произойдёт, если не выполнять заморозку своевременно?', 'Старые строки удалятся автоматически', 'Старые строки удалятся сервером автоматически', 'Старые строки сами не удаляются.', NULL),
        ('option', 'Что произойдёт, если не выполнять заморозку своевременно?', 'Отключится автоочистка', 'Автоочистка отключится до ручного VACUUM', 'Автоочистка не отключается; защитная очистка запускается даже при выключенной автоочистке.', NULL),
        ('option', 'Какой процесс планирует работу автоочистки и запускает рабочие процессы?', 'checkpointer', 'logical replication launcher', 'Выполняет контрольные точки.', 'Запускает процессы логической репликации, а не автоочистки.'),
        ('option', 'Возвращает ли обычный VACUUM освободившееся место операционной системе?', 'Да, всегда', 'Да: файл таблицы сразу уменьшается до размера данных', 'Обычно нет.', 'Обычно нет: системе возвращается только пустой хвост файла.'),
        ('option', 'Возвращает ли обычный VACUUM освободившееся место операционной системе?', 'Да, если таблица меньше 1 ГБ', 'Да, если таблица занимает меньше 1 ГБ', 'Размер таблицы здесь роли не играет.', NULL),
        ('option', 'Возвращает ли обычный VACUUM освободившееся место операционной системе?', 'Только для индексов', 'Да, но место освобождается в индексах, не в таблице', 'Нет. VACUUM может вернуть ОС пустые страницы в конце файла таблицы, поэтому ответ «только для индексов» неверен. В B-tree освободившиеся страницы используются повторно; чтобы уменьшить файл индекса, его перестраивают.', 'Нет: в B-tree освободившиеся страницы используются повторно, а файл индекса сам не уменьшается; уменьшить его можно перестроением.'),
        ('option', 'Возвращает ли обычный VACUUM освободившееся место операционной системе?', 'Как правило, нет: место внутри страниц используется для новых данных', 'Как правило, нет: место остаётся для новых версий', 'Системе возвращается только пустой хвост файла.', 'Освободившееся место внутри страниц используется для новых версий строк; системе возвращается только пустой хвост файла.'),
        ('option', 'Чем VACUUM FULL отличается от обычного VACUUM?', 'Работает без блокировок и быстрее', 'Работает без блокировок и быстрее обычной очистки таблицы', 'Наоборот: требует исключительной блокировки и работает дольше.', NULL),
        ('option', 'Чем VACUUM FULL отличается от обычного VACUUM?', 'Только собирает статистику', 'Собирает статистику вместо удаления мёртвых версий', 'Так работает ANALYZE.', 'Статистику собирает ANALYZE.'),
        ('option', 'Чем VACUUM FULL отличается от обычного VACUUM?', 'Полностью перезаписывает таблицу и индексы и требует исключительной блокировки', 'Перезаписывает таблицу и индексы под исключительной блокировкой', 'Таблица на это время недоступна даже для чтения.', NULL),
        ('option', 'Чем VACUUM FULL отличается от обычного VACUUM?', 'Очищает только индексы', 'Очищает индексы, не трогая саму таблицу', 'Перестраивает и таблицу, и индексы.', NULL),
        ('option', 'Какое ограничение есть у REINDEX ... CONCURRENTLY?', 'Нельзя запускать внутри явного блока транзакции; не поддерживает индексы системных каталогов', 'Нельзя запускать внутри блока транзакции BEGIN … COMMIT', 'Команда сама выполняет несколько этапов в отдельных транзакциях, поэтому её нельзя включить в блок BEGIN…COMMIT. Индексы системных каталогов в этом режиме не перестраиваются.', 'Команда сама выполняет несколько этапов в отдельных транзакциях, поэтому её нельзя включить в блок BEGIN…COMMIT. Индексы системных каталогов в этом режиме тоже не перестраиваются.'),
        ('option', 'Какое ограничение есть у REINDEX ... CONCURRENTLY?', 'Работает только при выключенной автоочистке', 'Требует выключенной автоочистки на время работы', 'От автоочистки не зависит.', NULL),
        ('option', 'Какое ограничение есть у REINDEX ... CONCURRENTLY?', 'Всегда выполняется быстрее обычного REINDEX', 'Выполняется быстрее, чем обычный REINDEX того же индекса', 'Обычно работает дольше обычного REINDEX.', 'Обычно работает дольше обычного REINDEX: индекс строится в несколько проходов.'),
        ('option', 'Что верно для команды VACUUM FULL?', 'Только собирает статистику', 'Собирает статистику для планировщика', 'Статистику собирает ANALYZE.', NULL),
        ('option', 'Для чего служит карта свободного пространства таблицы?', 'Хранит мёртвые версии строк до очистки', 'Хранит мёртвые версии строк до прихода очистки', 'Мёртвые версии лежат в самих страницах таблицы.', NULL),
        ('option', 'Для чего служит карта свободного пространства таблицы?', 'Показывает свободное место на диске', 'Показывает свободное место в файловой системе сервера', 'Свободное место на диске смотрят средствами ОС, например df.', NULL),
        ('option', 'Для чего служит карта свободного пространства таблицы?', 'Отмечает свободное место в страницах и помогает быстро найти место для новых версий строк', 'Помогает быстро найти страницу с местом для новой версии', 'Объём меняется: при вставке уменьшается, при очистке растёт.', 'Карта хранит примерный объём свободного места в каждой странице: при вставке он уменьшается, при очистке растёт.'),
        ('option', 'Что отмечается в карте свободного пространства индекса?', 'Только полностью пустые страницы, которые можно использовать заново', 'Полностью пустые страницы индекса', 'Индексная запись вставляется в строго определённое место, поэтому частично свободное место не учитывается.', 'Индексная запись вставляется в строго определённое место, поэтому частично свободное место не учитывается; пустые страницы можно использовать заново.'),
        ('option', 'Как карта видимости ускоряет доступ только по индексу?', 'Сжимает индекс', 'Сжимает индекс, чтобы он читался быстрее', 'Карта видимости размер индекса не меняет.', NULL),
        ('option', 'Как карта видимости ускоряет доступ только по индексу?', 'Если страница отмечена, видимость строки не нужно проверять по таблице', 'Видимость отмеченных страниц не проверяется по таблице', 'Когда все нужные столбцы есть в индексе, к таблице можно не обращаться.', 'Если страница отмечена в карте и все нужные столбцы есть в индексе, к таблице можно не обращаться.'),
        ('option', 'Как карта видимости ускоряет доступ только по индексу?', 'Отмечает пустые страницы индекса', 'Отмечает пустые страницы индекса для пропуска', 'Это делает карта свободного пространства индекса.', NULL),
        ('option', 'Как карта видимости ускоряет доступ только по индексу?', 'Хранит копии индексных записей', 'Хранит копии нужных столбцов таблицы рядом с индексом', 'Карта видимости хранит лишь биты для страниц таблицы.', NULL),
        ('option', 'Как карта видимости помогает самой очистке?', 'Никак не помогает', 'Карта нужна сканированию индекса, а не очистке', 'Это одно из двух главных применений карты видимости.', 'Это одно из двух главных применений карты видимости: очистка пропускает отмеченные страницы.'),
        ('option', 'Как карта видимости помогает самой очистке?', 'Очистка обрабатывает только отмеченные страницы', 'Очистка обрабатывает отмеченные страницы в первую очередь', 'Наоборот: отмеченные страницы можно пропустить.', 'Наоборот: отмеченные страницы можно пропустить, мёртвых версий в них нет.'),
        ('option', 'Как карта видимости помогает самой очистке?', 'Очистка может пропускать страницы, отмеченные в карте видимости', 'Очистка может пропускать отмеченные страницы', 'В таких страницах нет мёртвых версий; заморозка всё же заглядывает в страницы, ещё не отмеченные как полностью замороженные.', NULL),
        ('option', 'Как карта видимости помогает самой очистке?', 'Определяет порядок обработки таблиц', 'Определяет порядок обработки таблиц автоочисткой', 'Карта видимости порядок не задаёт: автоочистка выбирает таблицы по объёму изменений.', NULL),
        ('option', 'Как PostgreSQL собирает статистику для планировщика?', 'Только по индексам таблицы', 'По данным индексов, без чтения таблицы', 'Статистика собирается по данным таблицы.', NULL),
        ('option', 'Как PostgreSQL собирает статистику для планировщика?', 'Из записей журнала предзаписи', 'Из журнала предзаписи за прошедший период', 'Журнал хранит изменения для восстановления, а не статистику.', NULL),
        ('option', 'Что означает, что версия строки заморожена?', 'Она ждёт удаления очисткой', 'Она отмечена как мёртвая и ждёт удаления при очистке', 'Удаления ждут мёртвые версии, а не замороженные.', NULL),
        ('option', 'Что означает, что версия строки заморожена?', 'Её больше нельзя изменить или удалить', 'Её можно читать, но нельзя изменить или удалить', 'Замороженную версию можно обновить или удалить, как обычную.', NULL),
        ('option', 'Что означает, что версия строки заморожена?', 'Создавшая её транзакция считается завершённой в прошлом для любого снимка, и её номер больше не важен', 'Создавшая её транзакция считается давно завершённой', 'Этот номер можно использовать повторно после перехода счётчика через ноль.', 'Создавшая её транзакция считается завершённой в прошлом для любого снимка, и её номер больше не важен: его можно использовать повторно после перехода счётчика через ноль.'),
        ('option', 'Что означает, что версия строки заморожена?', 'Она перенесена в архив', 'Она перенесена в архивную часть таблицы', 'Заморозка — признак версии, сама версия остаётся на месте.', NULL),
        ('option', 'Что отмечает дополнительный бит в карте видимости?', 'Страницы, на которых все версии строк уже заморожены', 'Страницы, где все версии строк заморожены', 'Это позволяет не просматривать лишние страницы при заморозке.', NULL),
        ('option', 'Чем автоочистка лучше очистки по расписанию?', 'Реагирует на активность изменений: активные таблицы обрабатываются чаще', 'Обрабатывает таблицы чаще там, где больше изменений', 'Расписание либо создаёт лишнюю нагрузку, либо не успевает за изменениями.', 'Автоочистка реагирует на активность изменений; расписание либо создаёт лишнюю нагрузку, либо не успевает за изменениями.'),
        ('option', 'К чему приводит отключение автоочистки, если не выполнять очистку и анализ вручную?', 'К заметному ускорению запросов', 'К ускорению запросов за счёт экономии ввода-вывода', 'Кажущаяся экономия ввода-вывода оборачивается гораздо худшими последствиями.', NULL),
        ('option', 'Почему индекс-B-дерево не уменьшается даже после удаления большинства записей?', 'Страницы, получившиеся при расщеплении, больше не объединяются', 'Страницы после расщепления больше не объединяются', 'Частично заполненные страницы после расщепления не объединяются; полностью пустые используются повторно, но файл индекса не сжимается.', NULL),
        ('option', 'Почему индекс-B-дерево не уменьшается даже после удаления большинства записей?', 'Индексы вообще не очищаются', 'Очистка не убирает из индексов мёртвые ссылки', 'Очистка убирает из индексов ссылки на мёртвые версии строк.', NULL),
        ('option', 'Почему индекс-B-дерево не уменьшается даже после удаления большинства записей?', 'Удалённые записи переносятся в toast-таблицу', 'Удалённые записи переносятся в TOAST-таблицу индекса', 'TOAST к индексным записям не относится.', NULL),
        ('option', 'Что блокирует команда REINDEX?', 'Только чтение таблицы', 'Чтение таблицы, но не запись в неё', 'Блокируется запись в таблицу и использование индекса.', NULL),
        ('option', 'Что блокирует команда REINDEX?', 'Запись в таблицу и использование перестраиваемого индекса', 'Запись в таблицу и использование этого индекса', 'Транзакции, изменяющие таблицу или планирующие запрос к ней, будут приостановлены.', NULL),
        ('option', 'Что блокирует команда REINDEX?', 'Ничего не блокирует', 'Ничего: индекс перестраивается рядом со старым', 'Без блокировки изменений работает REINDEX CONCURRENTLY.', 'Без блокировки изменений работает REINDEX CONCURRENTLY, а обычный REINDEX блокирует запись.'),
        ('option', 'Что блокирует команда REINDEX?', 'Работу всего кластера', 'Все таблицы базы данных на время работы', 'Блокировки касаются только таблицы и её индекса.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
